entries=next(ast.literal_eval(n.value) for n in tree2.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='entries' for t in n.targets));entries.pop(3)
details=[
('Antarmuka ini menjadi halaman masuk bagi admin dan guru. Formulir menyediakan kolom alamat email dan kata sandi, pilihan Ingat saya, tombol Masuk, serta tombol untuk menampilkan atau menyembunyikan kata sandi. Tautan Lupa kata sandi ditampilkan apabila pemulihan kata sandi diaktifkan. Setelah autentikasi berhasil, pengguna diarahkan sesuai hak aksesnya.',
['Masuk: alamat email (email), kata sandi (password), dan pilihan Ingat saya (remember).','Tampil/Sembunyikan Kata Sandi: aksi pada tombol visibilitas di kolom kata sandi.','Lupa kata sandi: aksi pada tautan pemulihan kata sandi jika tersedia.'],
['Formulir login beserta keadaan terlihat atau tersembunyinya kata sandi.','Pesan validasi di kolom email atau kata sandi apabila proses autentikasi gagal.','Indikator proses pada tombol Masuk ketika permintaan sedang dikirim.','Akses ke dashboard admin atau halaman repository sesuai hak pengguna; halaman pemulihan jika tautan Lupa kata sandi dipilih.']),
('Antarmuka ini menyediakan formulir pendaftaran calon siswa pada periode PPDB yang sedang dibuka. Calon siswa atau orang tua memilih periode, melengkapi identitas calon siswa dan kontak orang tua, kemudian mengirimkan pendaftaran. Sistem memeriksa kelengkapan isian, NISN, serta periode sebelum menyimpan pendaftaran dengan status menunggu.',
['Get Periode: permintaan menampilkan daftar periode PPDB aktif.','Kirim Pendaftaran: periode PPDB (periode_ppdb_id), nama lengkap (nama_lengkap), NISN (nisn), jenis kelamin (jenis_kelamin), tempat lahir (tempat_lahir), tanggal lahir (tanggal_lahir), asal sekolah (asal_sekolah), nama orang tua (nama_orang_tua), nomor HP (no_hp), email opsional (email), dan alamat (alamat).'],
['Daftar periode yang dapat dipilih pada formulir.','Pesan kesalahan untuk isian yang tidak valid, termasuk NISN yang sudah terdaftar atau periode yang sudah ditutup.','Pemberitahuan keberhasilan pengiriman pendaftaran.','Indikator proses pengiriman untuk mencegah pengiriman berulang.']),
('Antarmuka dashboard membantu admin memantau ringkasan akademik dan PPDB. Halaman menampilkan jumlah siswa aktif, guru aktif, kelas, dan pendaftar, grafik status pendaftaran, grafik siswa aktif per kelas, serta pendaftar terbaru. Pilihan periode digunakan untuk mengubah ringkasan PPDB. Guru yang tidak memiliki hak admin diarahkan ke pengelolaan repository.',
['Get Dashboard: permintaan membuka halaman dashboard menggunakan sesi pengguna.','Pilih Periode: ID periode PPDB (periode_ppdb_id) pada dropdown periode.','Navigasi Menu: pilihan menu pada sidebar sesuai hak akses pengguna.'],
['Kartu ringkasan jumlah siswa aktif, guru aktif, kelas, dan pendaftar pada periode terpilih.','Grafik status menunggu, diterima, dan ditolak; grafik siswa aktif per kelas.','Daftar pendaftar terbaru dan informasi siswa aktif yang belum memiliki kelas.','Ringkasan PPDB yang diperbarui setelah pemilihan periode, atau halaman modul setelah navigasi.']),
('Antarmuka ini digunakan admin untuk memeriksa daftar calon siswa dan menentukan hasil penerimaan. Tabel menampilkan NISN, nama, asal sekolah, nomor HP, dan status. Admin dapat mencari data pada daftar, menyaring status, menerima atau menolak pendaftar, serta menghapus pendaftaran setelah konfirmasi.',
['Get: permintaan menampilkan daftar pendaftar PPDB.','Search: kata kunci pada kolom Cari untuk menyaring data yang sudah ditampilkan.','Filter Status: Semua Status, Menunggu, Diterima, atau Ditolak.','Terima: ID pendaftar yang dipilih dan status diterima.','Tolak: ID pendaftar yang dipilih dan status ditolak.','Hapus: ID pendaftar dan jawaban pada konfirmasi penghapusan.'],
['Daftar NISN, nama, asal sekolah, nomor HP, dan status pendaftar.','Hasil pencarian, hasil penyaringan status, dan jumlah data yang ditampilkan.','Status pendaftar terbaru setelah tindakan Terima atau Tolak.','Data siswa yang tersedia melalui proses penerimaan apabila persyaratannya terpenuhi.','Dialog konfirmasi penghapusan, daftar setelah penghapusan, atau pesan kesalahan perubahan status.']),
('Antarmuka ini digunakan admin untuk menetapkan jadwal dan informasi kuota PPDB. Daftar periode menyajikan nama, waktu mulai dan selesai, kuota, jumlah pendaftar, serta jumlah diterima. Formulir tambah dan edit memungkinkan pengaturan waktu pendaftaran; periode yang sudah memiliki pendaftar dilindungi dari penghapusan.',
['Get/Search: permintaan daftar periode dan kata kunci pencarian.','Tambah Periode: nama periode (nama_periode), tanggal dan waktu mulai (tanggal_mulai), tanggal dan waktu selesai (tanggal_selesai), serta kuota opsional (kuota).','Edit Periode: ID periode dan kolom nama, waktu mulai, waktu selesai, serta kuota yang diperbarui.','Hapus Periode: ID periode dan konfirmasi penghapusan.','Batal/Tutup: aksi menutup formulir tanpa menyimpan; Coba lagi: permintaan memuat ulang daftar setelah gagal.'],
['Daftar nama periode, waktu mulai dan selesai, kuota, jumlah pendaftar, dan jumlah diterima.','Formulir kosong saat tambah atau formulir berisi data saat edit.','Pesan validasi, termasuk tanggal selesai yang harus setelah tanggal mulai.','Pesan hasil penyimpanan atau penghapusan dan daftar yang diperbarui.','Dialog konfirmasi dan pesan penolakan penghapusan bila periode memiliki pendaftar.']),
('Antarmuka ini memfasilitasi pengelolaan identitas, kontak, kelas, dan status siswa oleh admin. Daftar siswa dilengkapi pencarian, filter kelas dan status, formulir tambah atau edit, serta tindakan Luluskan, Aktifkan Kembali, dan Hapus. Pemilihan Edit memuat isian siswa terpilih sehingga admin dapat memperbaruinya.',
['Get: permintaan daftar siswa dan pilihan kelas.','Search & Filter: kata kunci pencarian, pilihan kelas (kelas_id), dan status Semua Status, Aktif, Lulus, Pindah, atau Keluar.','Tambah Siswa: NIS (nis), NISN (nisn), nama lengkap (nama_lengkap), jenis kelamin (jenis_kelamin), tempat lahir (tempat_lahir), tanggal lahir (tanggal_lahir), nama orang tua/wali (nama_orang_tua), nomor HP (no_hp), email opsional (email), alamat (alamat), pilihan kelas opsional (kelas_id), dan status (status).','Edit: ID siswa serta seluruh kolom pada formulir Tambah Siswa yang diperbarui.','Luluskan/Aktifkan Kembali: ID siswa serta status lulus atau aktif.','Hapus: ID siswa dan konfirmasi penghapusan; Batal/Tutup: aksi menutup formulir.'],
['Tabel NIS, NISN, nama, jenis kelamin, kelas, nomor HP, dan status.','Daftar hasil pencarian dan filter beserta jumlah data yang ditampilkan.','Formulir tambah atau edit beserta pilihan kelas.','Pesan validasi pada isian dan daftar yang diperbarui setelah penyimpanan.','Status terbaru setelah Luluskan atau Aktifkan Kembali.','Dialog konfirmasi penghapusan, daftar setelah dihapus, atau pesan kegagalan proses.']),
('Antarmuka ini digunakan admin untuk mengelola identitas guru, kontak, mata pelajaran, dan status keaktifan. Halaman menyediakan daftar guru, pencarian, filter status, serta tombol Tambah Guru, Edit, dan Hapus. Formulir menyediakan pilihan mata pelajaran agar guru dikaitkan dengan data mata pelajaran yang tersedia.',
['Get/Search & Filter: permintaan daftar guru, kata kunci pencarian, dan pilihan Semua Status, Aktif, atau Nonaktif.','Tambah Guru: NIP opsional (nip), nama lengkap (nama_lengkap), jenis kelamin (jenis_kelamin), tempat lahir (tempat_lahir), tanggal lahir (tanggal_lahir), mata pelajaran (mata_pelajaran_id), nomor HP (no_hp), email opsional (email), alamat (alamat), dan status (status).','Edit: ID guru serta seluruh kolom formulir guru yang diperbarui.','Hapus: ID guru dan konfirmasi; Batal/Tutup: aksi menutup formulir.'],
['Tabel NIP, nama, jenis kelamin, mata pelajaran, nomor HP, dan status guru.','Hasil pencarian dan penyaringan status beserta jumlah data yang ditampilkan.','Formulir tambah atau edit beserta dropdown mata pelajaran.','Pesan validasi, misalnya NIP atau email yang sudah digunakan, dan daftar hasil penyimpanan.','Dialog konfirmasi penghapusan atau pesan kegagalan tindakan.']),
('Antarmuka ini membantu admin mengelola pembagian kelas dan penunjukan wali kelas. Daftar menampilkan nama kelas, tingkat, tahun ajaran, kapasitas, dan wali kelas. Tombol Tambah Kelas serta Edit membuka formulir yang sama dengan isian sesuai tindakan, sedangkan Hapus meminta konfirmasi sebelum menghapus kelas.',
['Get/Search: permintaan daftar kelas dan kata kunci pencarian.','Tambah Kelas: nama kelas (nama_kelas), tingkat VII/VIII/IX (tingkat), tahun ajaran (tahun_ajaran), kapasitas (kapasitas), dan wali kelas opsional (wali_kelas_id).','Edit: ID kelas serta nama kelas, tingkat, tahun ajaran, kapasitas, dan wali kelas yang diperbarui.','Hapus: ID kelas dan konfirmasi; Batal/Tutup: aksi menutup formulir.'],
['Tabel nama kelas, tingkat, tahun ajaran, kapasitas, serta nama wali kelas atau keterangan Belum ditentukan.','Daftar kelas hasil pencarian dan jumlah data yang ditampilkan.','Formulir tambah atau edit beserta pilihan guru wali kelas.','Pesan validasi format tahun ajaran atau duplikasi nama kelas pada tahun ajaran yang sama.','Daftar setelah penyimpanan atau penghapusan, dialog konfirmasi, dan pesan kegagalan jika proses tidak berhasil.']),
('Antarmuka ini digunakan admin untuk memelihara daftar mata pelajaran yang dipakai pada data guru dan repository. Halaman menyediakan daftar, pencarian, serta tindakan Tambah, Edit, dan Hapus. Formulir hanya memerlukan nama mata pelajaran dan memeriksa keunikan nama sebelum menyimpan.',
['Get/Search: permintaan daftar mata pelajaran dan kata kunci pencarian.','Tambah: nama mata pelajaran (nama).','Edit: ID mata pelajaran dan nama yang diperbarui.','Hapus: ID mata pelajaran serta konfirmasi; Batal/Tutup: aksi menutup formulir.','Coba lagi: permintaan ulang jika daftar gagal dimuat.'],
['Daftar mata pelajaran beserta hasil pencarian dan jumlah data yang ditampilkan.','Formulir tambah kosong atau formulir edit dengan nama sebelumnya.','Pesan kesalahan bila nama kosong atau sudah digunakan.','Daftar yang diperbarui setelah penyimpanan atau penghapusan.','Dialog konfirmasi dan pesan kegagalan pemuatan atau tindakan.']),
('Antarmuka ini memungkinkan admin menyusun pengumuman sekolah beserta gambar, tanggal berlaku, dan status publikasinya. Admin dapat membuat atau mengedit pengumuman, menyimpan sebagai draft, menerbitkan, mengembalikan ke draft, atau menghapusnya. Tabel memudahkan pemeriksaan judul, masa berlaku, status, serta pembuat pengumuman.',
['Get/Search: permintaan daftar pengumuman dan kata kunci pencarian.','Filter: pilihan status Semua Status, Terbit, atau Draft; halaman juga menyediakan pilihan target Semua Target, Siswa, Guru, Orang Tua, atau Umum.','Buat Pengumuman: judul (judul), isi (isi), gambar opsional (gambar), tanggal berlaku sampai opsional (berlaku_sampai), dan status draft/terbit sesuai tombol simpan.','Edit: ID pengumuman serta kolom judul, isi, tanggal akhir, dan gambar yang diperbarui; aksi buang gambar bila gambar lama dihapus.','Terbitkan/Jadikan Draft: ID pengumuman dan status terbit/draft.','Hapus: ID pengumuman serta konfirmasi; Batal/Tutup: aksi menutup formulir.'],
['Daftar gambar, judul, tanggal berlaku atau Tanpa batas, status, dan nama pembuat.','Daftar hasil pencarian atau penyaringan status serta jumlah data yang ditampilkan.','Formulir tambah atau edit dengan pratinjau gambar bila tersedia.','Pesan validasi isian atau gambar dan daftar yang diperbarui setelah disimpan.','Status publikasi terbaru setelah Terbitkan atau Jadikan Draft.','Dialog konfirmasi penghapusan atau pesan kegagalan perubahan status.']),
('Antarmuka ini digunakan admin untuk mengelola foto kegiatan dan penghargaan sekolah. Foto disajikan dalam daftar kartu yang dapat diedit atau dihapus. Formulir Tambah Foto menyediakan pemilihan berkas, pratinjau gambar, dan isian deskripsi; formulir edit memuat data sebelumnya dan memungkinkan penggantian gambar.',
['Get: permintaan menampilkan daftar galeri.','Tambah Foto: berkas gambar (gambar) dan deskripsi opsional (deskripsi).','Edit: ID galeri, deskripsi yang diperbarui, dan gambar pengganti jika diperlukan.','Hapus: ID galeri dan konfirmasi penghapusan.','Batal/Tutup: aksi menutup formulir; Coba lagi: permintaan memuat ulang galeri setelah gagal.'],
['Kartu foto galeri beserta deskripsinya jika tersedia.','Formulir tambah/edit serta pratinjau gambar yang dipilih.','Pesan validasi gambar atau deskripsi dan daftar foto yang diperbarui setelah penyimpanan.','Dialog konfirmasi penghapusan serta galeri setelah item dihapus.','Indikator pemuatan, keterangan galeri kosong, atau pesan gagal memuat galeri.']),
('Antarmuka ini memungkinkan admin dan guru mengelola dokumen pembelajaran berdasarkan mata pelajaran. Tabel menyediakan tindakan Edit, Hapus, dan Unduh, serta tombol Tambah Dokumen. Admin memiliki pengaturan tambahan untuk menyimpan kode akses repository dan mereset akses pengunjung. Reset membatalkan akses pengunjung lama sehingga kode perlu dimasukkan kembali.',
['Get/Search: permintaan daftar dokumen dan kata kunci pencarian.','Tambah Dokumen: mata pelajaran (mata_pelajaran_id), judul materi (judul), deskripsi opsional (deskripsi), dan berkas (file).','Edit: ID dokumen, mata pelajaran, judul, deskripsi, dan berkas pengganti jika diperlukan.','Unduh: ID dokumen terpilih; Hapus: ID dokumen dan konfirmasi.','Simpan Kode (admin): kode akses baru (kode) dan konfirmasi penyimpanan.','Reset Akses Pengunjung (admin): aksi tombol reset dan persetujuan pada dialog konfirmasi.','Batal/Tutup: aksi menutup formulir dokumen.'],
['Tabel judul materi, mata pelajaran, nama berkas, dan pembuat dokumen.','Daftar hasil pencarian dan jumlah data yang ditampilkan.','Formulir tambah atau edit serta pesan validasi isian atau berkas.','Berkas unduhan setelah akses dan ketersediaannya diperiksa.','Dialog konfirmasi penghapusan, penyimpanan kode, atau reset akses.','Daftar dokumen setelah perubahan dan pesan hasil pengaturan kode atau reset akses; pesan kegagalan jika tindakan tidak berhasil.']),
('Antarmuka ini menyediakan tiga formulir laporan PDF untuk admin, yaitu laporan PPDB, siswa, dan guru. Setiap formulir mempunyai filter tersendiri sehingga admin dapat memilih cakupan data sebelum mengunduh. Laporan PPDB mewajibkan pemilihan periode; filter lain dapat digunakan untuk membatasi hasil atau dibiarkan pada pilihan semua.',
['Get Pilihan: permintaan daftar periode PPDB dan kelas untuk dropdown.','Unduh Laporan PPDB: periode (periode_ppdb_id) serta status Semua Status, Menunggu, Diterima, atau Ditolak.','Unduh Laporan Siswa: kelas (kelas_id) atau Semua kelas serta status Semua Status, Aktif, Lulus, Pindah, atau Keluar.','Unduh Laporan Guru: status Semua Status, Aktif, atau Nonaktif.'],
['Tiga formulir laporan beserta pilihan periode, kelas, dan status yang relevan.','Berkas PDF pendaftar sesuai periode dan status yang dipilih.','Berkas PDF siswa sesuai kelas dan status; berkas PDF guru sesuai status.','Laporan dibuka melalui tab baru setelah tombol unduh dipilih.','Peringatan bila periode wajib belum dipilih serta pesan gagal memuat pilihan periode atau kelas.'])
]
assert len(details)==len(entries)==13
doc=Document();s=doc.sections[0];s.left_margin=Cm(3);s.right_margin=Cm(2.5);s.top_margin=Cm(2.5);s.bottom_margin=Cm(2.5)
for name in ['Normal','Title','Heading 1']:
 st=doc.styles[name];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0)
doc.styles['Normal'].font.size=Pt(11);doc.styles['Normal'].paragraph_format.space_after=Pt(5)
doc.add_heading('2.4 Perancangan Antarmuka',0)
doc.add_paragraph('Perancangan antarmuka menjelaskan tujuan halaman, kolom masukan menurut tindakan pengguna, keluaran yang ditampilkan, dan langkah proses untuk menjalankan setiap fitur.')
for i,((heading,*_), (desc,inp,out)) in enumerate(zip(entries,details),1):
 title=heading.replace('2. ','').replace('Pengguna Kelola','Kelola').strip()
 if i==3:title='Antarmuka Dashboard'
 doc.add_heading(f'2.4.{i} {title}',1)
 for label,values in [('Deskripsi',[desc]),('Input',inp),('Output',out)]:
  p=doc.add_paragraph();p.paragraph_format.keep_with_next=True;p.add_run(label+' :').bold=True
  for value in values:
   p=doc.add_paragraph()
   if label=='Input' and ': ' in value:
    a,b=value.split(': ',1);p.add_run(a+': ').bold=True;p.add_run(b)
   else:p.add_run(value)
 p=doc.add_paragraph();p.paragraph_format.keep_with_next=True;p.add_run('Method/Algoritma :').bold=True
 for action,steps in actions[heading]:
  p=doc.add_paragraph();p.paragraph_format.keep_with_next=True;p.add_run('On ‘'+action+'’').bold=True
  for j,step in enumerate(steps,1):
   p=doc.add_paragraph(f'{j}. {step}');p.paragraph_format.left_indent=Cm(.6);p.paragraph_format.first_line_indent=Cm(-.4)
path=root/'Penjelasan_Antarmuka_Bab_2.4_SIANGKASA_Revisi.docx';doc.save(path);print(path)
